//! WIT compatibility tests for WASM tools and channels.//!//! These tests verify that pre-built WASM components can be compiled and//! instantiated against the current host linker. If the WIT interface//! changes, these tests catch any breakage in existing tools/channels.//!//! Prerequisites: build WASM extensions first with://!   ./scripts/build-wasm-extensions.sh//!//! The tests are skipped (not failed) when no WASM artifacts are found,//! so `cargo test` still passes without building extensions first.//! CI runs the build script before these tests.use std::path::{Path, PathBuf};use wasmtime_wasi::{ResourceTable, WasiCtx, WasiCtxBuilder, WasiView};/// Minimal store data that satisfies WasiView for component instantiation.struct TestStoreData {    wasi: WasiCtx,    table: ResourceTable,}impl TestStoreData {    fn new() -> Self {        Self {            wasi: WasiCtxBuilder::new().build(),            table: ResourceTable::new(),        }    }}impl WasiView for TestStoreData {    fn ctx(&mut self) -> &mut WasiCtx {        &mut self.wasi    }    fn table(&mut self) -> &mut ResourceTable {        &mut self.table    }}/// Extension kind from the registry manifest.#[derive(Debug, Clone, Copy, PartialEq, Eq)]enum ExtensionKind {    Tool,    Channel,}/// A discovered WASM extension from the registry.struct DiscoveredExtension {    name: String,    source_dir: PathBuf,    crate_name: String,    kind: ExtensionKind,}/// Search paths for WASM artifacts produced by cargo-component.fn find_wasm_artifact(source_dir: &Path, crate_name: &str) -> Option<PathBuf> {    let artifact_name = crate_name.replace('-', "_");    // Crate-local target dir (CI, default cargo)    for target_triple in &["wasm32-wasip2", "wasm32-wasip1", "wasm32-wasi"] {        let candidate = source_dir            .join("target")            .join(target_triple)            .join("release")            .join(format!("{artifact_name}.wasm"));        if candidate.exists() {            return Some(candidate);        }    }    // Shared target dir (CARGO_TARGET_DIR env)    if let Ok(shared) = std::env::var("CARGO_TARGET_DIR") {        for target_triple in &["wasm32-wasip2", "wasm32-wasip1", "wasm32-wasi"] {            let candidate = Path::new(&shared)                .join(target_triple)                .join("release")                .join(format!("{artifact_name}.wasm"));            if candidate.exists() {                return Some(candidate);            }        }    }    // Common shared target location (~/.cargo/shared-target)    if let Some(home) = dirs::home_dir() {        let shared = home.join(".cargo/shared-target");        if shared.exists() {            for target_triple in &["wasm32-wasip2", "wasm32-wasip1", "wasm32-wasi"] {                let candidate = shared                    .join(target_triple)                    .join("release")                    .join(format!("{artifact_name}.wasm"));                if candidate.exists() {                    return Some(candidate);                }            }        }    }    None}/// Parse registry manifests to discover all WASM extensions.fn discover_extensions() -> Vec<DiscoveredExtension> {    let repo_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));    let mut extensions = Vec::new();    for dir in &["registry/tools", "registry/channels"] {        let registry_dir = repo_root.join(dir);        if !registry_dir.exists() {            continue;        }        for entry in std::fs::read_dir(&registry_dir).expect("failed to read registry dir") {            let entry = entry.expect("failed to read directory entry");            let path = entry.path();            if path.extension().and_then(|e| e.to_str()) != Some("json") {                continue;            }            let content = std::fs::read_to_string(&path).expect("failed to read manifest");            let manifest: serde_json::Value =                serde_json::from_str(&content).expect("failed to parse manifest");            let name = manifest["name"].as_str().unwrap_or("unknown").to_string();            let kind = match manifest["kind"].as_str() {                Some("tool") => ExtensionKind::Tool,                Some("channel") => ExtensionKind::Channel,                _ => continue,            };            let source_dir = manifest["source"]["dir"]                .as_str()                .map(|d| repo_root.join(d));            let crate_name = manifest["source"]["crate_name"]                .as_str()                .map(|s| s.to_string());            if let (Some(source_dir), Some(crate_name)) = (source_dir, crate_name)                && source_dir.exists()            {                extensions.push(DiscoveredExtension {                    name,                    source_dir,                    crate_name,                    kind,                });            }        }    }    extensions}